WITH valid_departments AS (SELECT *, LOWER(location) AS location_lower FROM departments WHERE (location NOT IN ('Singapore', 'New York', 'Tokyo') AND location IN ('London', 'Chiang Mai')) OR location = 'New York'), agg AS (SELECT CASE WHEN dept_name IN ('HR', 'Engineering') THEN 'tier_1' ELSE 'other' END AS dept_name_group, ROUND((100 * SUM(CASE WHEN location = 'Tokyo' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_tokyo, ROUND((100 * SUM(CASE WHEN dept_name = 'Sales' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_sales FROM valid_departments GROUP BY CASE WHEN dept_name IN ('HR', 'Engineering') THEN 'tier_1' ELSE 'other' END) SELECT * FROM agg ORDER BY pct_sales DESC
